def committed_plan(path: Path, *, root: Path):
    """Read a repository-approved plan; untracked or modified authority is refused."""
    relative = path.resolve().relative_to(root.resolve())
    git = shutil.which("git")
    if git is None:
        _fail("Git source authority is unavailable; synthetic admission is denied")
    result = proc.run(
        [git, "show", f"HEAD:{relative.as_posix()}"], cwd=root, check=False, timeout=5
    )
    content = result.stdout.encode()
    if result.returncode or content != path.read_bytes():
        _fail("Synthetic admission requires an unchanged committed evidence plan")
    return content

def _library_path() -> str | None:
    from ctypes.util import find_library
    import shutil

    path = find_library("rubberband")
    if path is None and sys.platform == "darwin" and (config := shutil.which("pkg-config")):
        from unstd import proc

        try:
            location = proc.run(
                [config, "--variable=libdir", "rubberband"],
                check=False,
                timeout=2,
            )
        except OSError, proc.TimeoutExpired:
            return None
        directory = location.stdout.strip()
        if location.returncode == 0 and directory:
            library = Path(directory, "librubberband.dylib")
            if library.is_file():
                return str(library.resolve())
    return path

