            )
            path = parsed.get("path") if isinstance(parsed, dict) else None
            if not isinstance(path, str):
                return None
            executable_path = path
        words = output([executable_path, "--version"], environment).split()
    except (TimeoutError, proc.TimeoutExpired) as exc:
        raise TimeoutError from exc
    except ImportError, AttributeError, OSError, proc.CalledProcessError, ValueError, KeyError:
